#include "kmb.hpp"
using V=bitset<841>;
constexpr int N=35,M=4095,Q=851,FLAG=49140,HM=49141;
int mul(int a,int b){int z=0;for(;b;b>>=1){if(b&1)z^=a;a<<=1;if(a&4096)a^=0x1053;}return z;}
U rng(U&z){z+=0x9e3779b97f4a7c15ULL;U x=z;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);}
int main(int argc,char**argv){K k(argv[1]);assert(k.Q==Q&&k.B==HM+1);int nr=0;set<string> regs;for(auto s:k.sections)if(s.k==0){I n,r;memcpy(&n,s.p,4);memcpy(&r,s.p+4,4);assert(r==12&&s.n==8+n+48);string name((char*)s.p+8,n);assert(regs.insert(name).second);int i=stoi(name.substr(1));assert(name[0]=='P'||name[0]=='V'||name[0]=='E');assert(i>=0&&i<(name[0]=='E'?M:N));int off=(name[0]=='V'?420:0)+i*12;for(int b=0;b<12;b++){I w;memcpy(&w,s.p+8+n+b*4,4);assert(w==(I(off+b)|(name[0]=='E'?0:0x80000000u)));}nr++;}assert(nr==M+2*N);
vector<V> s(840);for(int i=0;i<840;i++)s[i].set(i);vector<int> exp(M);exp[0]=1;for(int j=1;j<M;j++)exp[j]=mul(exp[j-1],2);assert(mul(exp.back(),2)==1&&set<int>(exp.begin(),exp.end()).size()==M);set<int> seen;U cc=0,hm=0,cx=0,sw=0,xx=0;
for(I i=0;i<k.N;i++){G g=k.next(i);auto expect=[&](int t,int a=-1,int b=-1,int c=-1,int m=0,int z=0){assert(++i<k.N);G h=k.next(i);assert(h.t==t&&h.a==a&&h.b==b&&h.c==c&&h.m==I(m)&&h.k==I(z));};if(g.t==33){assert(g.a<840&&g.b<840);s[g.b]^=s[g.a];cx++;}else if(g.t==34){assert(g.a<840&&g.b<840);swap(s[g.a],s[g.b]);sw++;}else if(g.t==17){assert(g.a<840);s[g.a].flip(840);xx++;}else if(g.t==64){assert(g.m==FLAG);G h=k.next(++i);assert(h.t==193&&h.m==FLAG&&h.k%12==0&&h.k<FLAG);int j=h.k/12;assert(seen.insert(j).second);for(int b=1;b<12;b++)expect(193,-1,-1,-1,FLAG,12*j+b);expect(129,-1,-1,-1,0,FLAG);array<V,12> p{},v{};int x=exp[j],y=1;for(int a=0;a<N;a++){for(int b=0;b<12;b++){int z=mul(y,1<<b);for(int c=0;c<12;c++)if(z>>c&1){p[c].set(a*12+b);v[c].set(420+a*12+b);}}y=mul(y,x);}for(int b=0;b<12;b++){if((y^4095)>>b&1)p[b].set(840);if(s[b]!=p[b]||s[420+b]!=v[b]){cerr<<"mismatch at point "<<j<<" bit "<<b<<" P "<<(s[b]^p[b]).count()<<" V "<<(s[420+b]^v[b]).count()<<endl;return 2;}}
expect(49,0,1,840);for(int b=2;b<12;b++)expect(49,838+b,b,839+b);for(int b=0;b<12;b++)expect(160,850,420+b,-1,0,12*j+b);for(int b=11;b>=2;b--){expect(80,839+b,-1,-1,HM);expect(160,838+b,b,-1,0,HM);}expect(80,840,-1,-1,HM);expect(160,0,1,-1,0,HM);expect(1);expect(64,-1,-1,-1,FLAG);cc+=11;hm+=11;
}else {cerr<<"unknown op "<<g.t<<" at "<<i<<endl;return 3;}}
assert(seen.size()==M);for(int i=0;i<840;i++){V a;a.set(i);assert(s[i]==a);}for(int i=2;i<=9;i++)assert(k.pos[i]*4==k.len[i]);cout<<argv[1]<<" exact affine evaluations="<<seen.size()<<" arbitrary coefficient/mask and independent HMR histories PASS; restore=PASS CCX="<<cc<<" HMR="<<hm<<" CX="<<cx<<" SWAP="<<sw<<" X="<<xx<<" ops="<<k.N<<endl;
if(argc<3)return 0;k.reset();vector<U> q(Q),c(k.B);U expected;ifstream f(argv[2],ios::binary);f.read((char*)q.data(),Q*8);f.read((char*)c.data(),k.B*8);f.read((char*)&expected,8);assert(f);auto init=q,ci=c;U active=~U(0),phase=0,seed=715,pay=0;vector<U> stack;for(I i=0;i<k.N;i++){G g=k.next(i);U a=active;if(g.t&128)a&=c[g.k];if(g.t==129){stack.push_back(active);active=a;continue;}if(g.t==1){assert(!stack.empty());active=stack.back();stack.pop_back();continue;}switch(g.t&127){case 17:q[g.a]^=a;break;case 33:q[g.b]^=a&q[g.a];break;case 34:{U x=a&(q[g.a]^q[g.b]);q[g.a]^=x;q[g.b]^=x;break;}case 49:q[g.c]^=a&q[g.a]&q[g.b];pay+=__builtin_popcountll(a);break;case 32:phase^=a&q[g.a]&q[g.b];break;case 64:c[g.m]&=~a;break;case 65:c[g.m]|=a;break;case 80:{U r=rng(seed);phase^=a&r&q[g.a];q[g.a]&=~a;c[g.m]=(c[g.m]&~a)|(a&r);break;}default:assert(false);}}assert(stack.empty());assert(q==init);assert(equal(c.begin(),c.begin()+FLAG,ci.begin()));assert(c[FLAG]==0);assert(phase==expected);cout<<"64 packed sparse-error cases PASS, zero output/phase errors, mean CCX="<<double(pay)/64<<endl;
}
